class Voronoi {
    private vertices: null;
    private edges: null;
    private cells: null;
    private toRecycle: null;
    private beachsectionJunkyard: never[];
    private circleEventJunkyard: never[];
    private vertexJunkyard: never[];
    private edgeJunkyard: never[];
    private cellJunkyard: never[];
    private reset: () => void;
    private beachline: any;
    private RBTree: any;
    private circleEvents: any;
    private firstCircleEvent: null;
    private sqrt: (x: number) => number;
    private abs: (x: number) => number;
    private ε: number;
    private invε: number;
    private equalWithEpsilon: (a: any, b: any) => boolean;
    private greaterThanWithEpsilon: (a: any, b: any) => boolean;
    private greaterThanOrEqualWithEpsilon: (a: any, b: any) => boolean;
    private lessThanWithEpsilon: (a: any, b: any) => boolean;
    private lessThanOrEqualWithEpsilon: (a: any, b: any) => boolean;
    private root: null;
    private Diagram: (site: any) => void;
    private site: any;
    private Cell: (site: any) => void;
    private halfedges: never[];
    private closeMe: boolean;
    private createCell: (site: any) => any;
    private Vertex: (x: any, y: any) => void;
    private x: any;
    private y: any;
    private Edge: (lSite: any, rSite: any) => void;
    private lSite: any;
    private rSite: any;
    private va: null;
    private vb: null;
    private Halfedge: (edge: any, lSite: any, rSite: any) => void;
    private edge: any;
    private angle: number;
    private createHalfedge: (edge: any, lSite: any, rSite: any) => any;
    private createVertex: (x: any, y: any) => any;
    private createEdge: (lSite: any, rSite: any, va: any, vb: any) => any;
    private setEdgeStartpoint(edge: any, lSite: any, rSite: any, va: any) {
      throw new Error("Method not implemented.");
    }
    private setEdgeEndpoint(edge: any, lSite: any, rSite: any, vb: any) {
      throw new Error("Method not implemented.");
    }
    private createBorderEdge: (lSite: any, va: any, vb: any) => any;
    private Beachsection: () => void;
    private createBeachsection: (site: any) => any;
    private leftBreakPoint: (arc: any, directrix: any) => any;
    private rightBreakPoint: (arc: any, directrix: any) => any;
    private detachBeachsection: (beachsection: any) => void;
    private detachCircleEvent(beachsection: any) {
      throw new Error("Method not implemented.");
    }
    private removeBeachsection: (beachsection: any) => void;
    private attachCircleEvent(lArc: any) {
      throw new Error("Method not implemented.");
    }
    private addBeachsection: (site: any) => void;
    private CircleEvent: () => void;
    private arc: null;
    private rbLeft: null;
    private rbNext: null;
    private rbParent: null;
    private rbPrevious: null;
