    compute: (sites: { x: number; y: number; voronoiId?: number | undefined; }[], bbox: { xl: number; xr: number; yt: number; yb: number; }) => any;
    constructor() {
        this.vertices = null;
        this.edges = null;
        this.cells = null;
        this.toRecycle = null;
        this.beachsectionJunkyard = [];
        this.circleEventJunkyard = [];
        this.vertexJunkyard = [];
        this.edgeJunkyard = [];
