// ---------------------------------------------------------------------------
// Helper: Quantize sites

// rhill 2013-10-12:
// This is to solve https://github.com/gorhill/Javascript-Voronoi/issues/15
// Since not all users will end up using the kind of coord values which would
// cause the issue to arise, I chose to let the user decide whether or not
// he should sanitize his coord values through this helper. This way, for
// those users who uses coord values which are known to be fine, no overhead is
// added.

Voronoi.prototype.quantizeSites = function (sites) {
    var ε = this.ε,
        n = sites.length,
        site;
    while (n--) {
        site = sites[n];
        site.x = Math.floor(site.x / ε) * ε;
        site.y = Math.floor(site.y / ε) * ε;
    }
};

// ---------------------------------------------------------------------------
// Helper: Recycle diagram: all vertex, edge and cell objects are
// "surrendered" to the Voronoi object for reuse.
// TODO: rhill-voronoi-core v2: more performance to be gained
// when I change the semantic of what is returned.

Voronoi.prototype.recycle = function (diagram) {
    if (diagram) {
        if (diagram instanceof this.Diagram) {
            this.toRecycle = diagram;
        }
        else {
            throw 'Voronoi.recycleDiagram() > Need a Diagram object.';
        }
    }
};

// ---------------------------------------------------------------------------
// Top-level Fortune loop

// rhill 2011-05-19:
//   Voronoi sites are kept client-side now, to allow
//   user to freely modify content. At compute time,
//   *references* to sites are copied locally.

Voronoi.prototype.compute = function (sites: {x: number, y: number, voronoiId?: number}[], bbox: {xl: number, xr: number, yt: number, yb: number}) {
    // to measure execution time
    var startTime = new Date();

    // init internal state
    this.reset();

    // any diagram data available for recycling?
    // I do that here so that this is included in execution time
    if (this.toRecycle) {
        this.vertexJunkyard = this.vertexJunkyard.concat(this.toRecycle.vertices);
        this.edgeJunkyard = this.edgeJunkyard.concat(this.toRecycle.edges);
        this.cellJunkyard = this.cellJunkyard.concat(this.toRecycle.cells);
        this.toRecycle = null;
    }

    // Initialize site event queue
    var siteEvents = sites.slice(0);
    siteEvents.sort(function (a, b) {
        var r = b.y - a.y;
        if (r) { return r; }
        return b.x - a.x;
    });

    // process queue
    var site = siteEvents.pop(),
        siteid = 0,
        xsitex, // to avoid duplicate sites
        xsitey,
        cells = this.cells,
        circle;

    // main loop
    for (; ;) {
        // we need to figure whether we handle a site or circle event
        // for this we find out if there is a site event and it is
        // 'earlier' than the circle event
        circle = this.firstCircleEvent;

        // add beach section
        if (site && (!circle || site.y < circle.y || (site.y === circle.y && site.x < circle.x))) {
            // only if site is not a duplicate
            if (site.x !== xsitex || site.y !== xsitey) {
                // first create cell for new site
                cells[siteid] = this.createCell(site);
                site.voronoiId = siteid++;
                // then create a beachsection for that site
                this.addBeachsection(site);
                // remember last site coords to detect duplicate
                xsitey = site.y;
                xsitex = site.x;
            }
            site = siteEvents.pop();
        }

        // remove beach section
        else if (circle) {
            this.removeBeachsection(circle.arc);
        }

        // all done, quit
        else {
            break;
        }
    }

    // wrapping-up:
    //   connect dangling edges to bounding box
    //   cut edges as per bounding box
    //   discard edges completely outside bounding box
    //   discard edges which are point-like
    this.clipEdges(bbox);

    //   add missing edges in order to close opened cells
    this.closeCells(bbox);

    // to measure execution time
    var stopTime = new Date();

    // prepare return values
    var diagram = new this.Diagram();
    diagram.cells = this.cells;
    diagram.edges = this.edges;
    diagram.vertices = this.vertices;
    diagram.execTime = stopTime.getTime() - startTime.getTime();

    // clean up
    this.reset();

    return diagram;
};

type VDiagram = {
  cells: VCell[],
}

type VCell = {
  site: VSite,
  halfedges: VHalfedge[]
}

type VSite = {
  x: number,
  y: number,
  voronoiId: number
}

type VHalfedge = {
  getStartpoint(): { x: number, y: number },
  getEndpoint(): { x: number, y: number }
}

function getVoronoiPolygons(diagram: VDiagram, origSiteList?: VSite[]): { x: number, y: number }[][] {
  const idSortedCells = origSiteList?.map(s => diagram.cells[s.voronoiId]) ?? diagram.cells
  return idSortedCells.map(cell => {
    return cell.halfedges.map(halfedge => {
      return halfedge.getStartpoint()
    })
  })
}

//a list of points in a polygon in the order they appear in the polygon
export function filterSimilarPoints(points: { x: number, y: number }[], threshold: number=0.002) {
    const indexesTooCloseToPrevious = new Set<number>()
    for (let i = 0; i < points.length-1; i++) {
      const pt = points[i]
      const nextPt = points[i+1]
      if(Math.abs(pt.x - nextPt.x) < threshold && Math.abs(pt.y - nextPt.y) < threshold) {
        indexesTooCloseToPrevious.add(i+1)
      }
    }

    const pt = points[0]
    const nextPt = points[points.length-1]
    if(Math.abs(pt.x - nextPt.x) < threshold && Math.abs(pt.y - nextPt.y) < threshold) {
      indexesTooCloseToPrevious.add(points.length-1)
    }

    const filteredPts = points.filter((pt, i) => !indexesTooCloseToPrevious.has(i))

    //check first and last point - if too close, remove last point - quick hack instead of making sure logic above catches this
    const pt2 = filteredPts[0]
    const nextPt2 = filteredPts[filteredPts.length-1]
    if(Math.abs(pt2.x - nextPt2.x) < threshold && Math.abs(pt2.y - nextPt2.y) < threshold) {
      filteredPts.pop()
    }

    return filteredPts
  }

/******************************************************************************/

export {
    Voronoi,
    getVoronoiPolygons
}

