    this.passCount = passCount;

    const primaryTextureKey = options.primaryTextureKey ?? this.inputKeys[0];
    if (!primaryTextureKey) {
      throw new Error('CustomShaderEffect requires a primaryTextureKey to manage multi-pass routing');
    }
    if (!this.inputKeys.includes(primaryTextureKey)) {
      throw new Error(`Primary texture key ${primaryTextureKey} must be one of the textureInputKeys`);
    }
    this.primaryTextureKey = primaryTextureKey;

    this.passMaterials = [];
    for (let i = 0; i < passCount; i += 1) {
      this.passMaterials.push(options.factory(device, this.format, { name: 'ShaderFXMaterial', passIndex: i }));
    }

    this.passTextureSources = this.initializePassTextureSources(options.passTextureSources, passCount);
    const requestedPingPong = options.pingPong ?? (passCount > 1);
    let pingPong = requestedPingPong && passCount > 1;
    if (pingPong) {
      const invalid = this.passTextureSources.some((bindings, passIndex) =>
        bindings.some((binding) => binding.kind === 'pass' && binding.passIndex !== passIndex - 1)
      );
      if (invalid) {
        console.warn('ShaderFX ping-pong disabled: passTextureSources reference non-previous passes.');
        pingPong = false;
      }
    }
    this.pingPong = pingPong;

    const intermediateCount = passCount > 1 ? (this.pingPong ? 2 : passCount - 1) : 0;
    this.passTextures = new Array(intermediateCount).fill(null);
    this.passViews = new Array(intermediateCount).fill(null);

    this.uniformMeta = options.uniformMeta ? [...options.uniformMeta] : [];

    this.outputTexture = device.createTexture({
      size: { width: this.width, height: this.height },
      format: this.format,
      usage: GPUTextureUsage.RENDER_ATTACHMENT | GPUTextureUsage.TEXTURE_BINDING | GPUTextureUsage.COPY_SRC,
    });
    this.output = this.outputTexture.createView();
  }

  setSrcs(inputs: Partial<I>): void {
    this.inputs = { ...this.inputs, ...inputs };
  }

  setUniforms(uniforms: ShaderUniforms): void {
    this.uniforms = { ...this.uniforms, ...uniforms };
    this.updateUniforms();
  }

  updateUniforms(): void {
    const record: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(this.uniforms)) {
      record[key] = extract(value as Dynamic<unknown>);
    }
    const resolved = record as Partial<U>;
    for (const material of this.passMaterials) {
      material.setUniforms(resolved);
    }
  }

  protected initializePassTextureSources(
    sources: readonly (readonly PassTextureSourceSpec<I>[])[] | undefined,
    passCount: number,
  ): RuntimePassTextureSource<I>[][] {
    if (!sources || sources.length === 0) {
      return this.buildDefaultPassTextureSources(passCount);
    }

    const normalized: RuntimePassTextureSource<I>[][] = [];
    for (let passIndex = 0; passIndex < passCount; passIndex += 1) {
      const entries = sources[passIndex] ?? [];
      const normalizedEntries: RuntimePassTextureSource<I>[] = [];
      for (const entry of entries) {
        if (entry.source.kind === 'input') {
          normalizedEntries.push({ binding: entry.binding, kind: 'input', key: entry.source.key });
        } else {
          const dependency = entry.source.passIndex;
          if (dependency >= passIndex) {
            throw new Error(`Pass ${passIndex} can only depend on earlier passes. Received dependency on pass${dependency}.`);
          }
          normalizedEntries.push({ binding: entry.binding, kind: 'pass', passIndex: dependency });
        }
      }
      const seenBindings = new Set(normalizedEntries.map((entry) => entry.binding));
      for (const binding of this.textureBindingKeys) {
        if (seenBindings.has(binding)) {
          continue;
        }
        const candidateKey = binding as TextureInputKey<I>;
        if (this.inputKeys.includes(candidateKey)) {
          normalizedEntries.push({ binding, kind: 'input', key: candidateKey });
        }
      }
      normalized.push(normalizedEntries);
    }
    return normalized;
  }

  protected buildDefaultPassTextureSources(passCount: number): RuntimePassTextureSource<I>[][] {
    const sources: RuntimePassTextureSource<I>[][] = [];
    for (let passIndex = 0; passIndex < passCount; passIndex += 1) {
      const entries: RuntimePassTextureSource<I>[] = [];
      for (const binding of this.textureBindingKeys) {
        if (binding === this.primaryTextureKey && passIndex > 0) {
          entries.push({ binding, kind: 'pass', passIndex: passIndex - 1 });
          continue;
        }
        const candidateKey = binding as TextureInputKey<I>;
        if (this.inputKeys.includes(candidateKey)) {
          entries.push({ binding, kind: 'input', key: candidateKey });
        }
      }
      sources.push(entries);
    }
    return sources;
  }

  protected ensurePassTexture(passIndex: number): GPUTextureView {
    const slot = this.pingPong ? passIndex % 2 : passIndex;
    const existing = this.passViews[slot];
    if (existing) {
      return existing;
    }
    const texture = this.device.createTexture({
      size: { width: this.width, height: this.height },
      format: this.format,
      usage: GPUTextureUsage.RENDER_ATTACHMENT | GPUTextureUsage.TEXTURE_BINDING | GPUTextureUsage.COPY_SRC,
    });
    const view = texture.createView();
    this.passTextures[slot] = texture;
    this.passViews[slot] = view;
    return view;
  }

  protected resolveInputs(): Partial<Record<TextureInputKey<I>, GPUTextureView>> {
    const resolved: Partial<Record<TextureInputKey<I>, GPUTextureView>> = {};
    for (const key of this.inputKeys) {
      const source = this.inputs[key];
      if (!source) {
        continue;
      }
      resolved[key] = resolveTexture(source);
    }
    return resolved;
  }

  protected applySourcesForPass(
    passIndex: number,
    resolvedInputs: Partial<Record<TextureInputKey<I>, GPUTextureView>>,
    passOutputs: Array<GPUTextureView | undefined>,
  ): void {
    const handles = this.passMaterials[passIndex];
    const bindings = this.passTextureSources[passIndex] ?? [];
    for (const binding of bindings) {
      let view: GPUTextureView | undefined;
      if (binding.kind === 'input') {
        view = resolvedInputs[binding.key];
      } else {
        view = passOutputs[binding.passIndex];
      }
      if (!view) {
        continue;
      }
      handles.setTexture(binding.binding, view);
    }
  }

  render(): void {
    const resolvedInputs = this.resolveInputs();
    this.updateUniforms();

    const encoder = this.device.createCommandEncoder();
    const passOutputs: Array<GPUTextureView | undefined> = [];

    for (let passIndex = 0; passIndex < this.passCount; passIndex += 1) {
      const isFinal = passIndex === this.passCount - 1;
      const outputView = isFinal ? this.output : this.ensurePassTexture(passIndex);

      this.applySourcesForPass(passIndex, resolvedInputs, passOutputs);

      const material = this.passMaterials[passIndex];
      const pass = encoder.beginRenderPass({
        colorAttachments: [
          {
            view: outputView,
            clearValue: this.clearColor,
            loadOp: 'clear',
            storeOp: 'store',
          },
        ],
      });

      pass.setPipeline(material.pipeline);
      pass.setBindGroup(0, material.bindGroup);
      pass.draw(3);
      pass.end();

      passOutputs[passIndex] = outputView;
    }

    this.device.queue.submit([encoder.finish()]);
  }

  dispose(): void {
    this.outputTexture.destroy();
    for (const texture of this.passTextures) {
      texture?.destroy();
    }
  }
}

export type PassthruUniforms = Record<string, never>;
export type PassthruTextureName = 'src';

export interface PassthruInputs {
  src: ShaderSource;
}

export interface PassthruMaterialHandles extends MaterialHandles<PassthruUniforms, PassthruTextureName> {}

export interface PassthruMaterialOptions {
  name?: string;
  sampleMode?: 'nearest' | 'linear';
}

export function createPassthruMaterial(
  device: GPUDevice,
  format: GPUTextureFormat,
  options: PassthruMaterialOptions = {},
): PassthruMaterialHandles {
  const name = options.name ?? 'PassthruMaterial';
  const sampleMode = options.sampleMode ?? 'linear';

  const bindGroupLayout = device.createBindGroupLayout({
    entries: [
      { binding: 0, visibility: GPUShaderStage.FRAGMENT, texture: { sampleType: 'float' } },
      { binding: 1, visibility: GPUShaderStage.FRAGMENT, sampler: { type: 'filtering' } },
    ],
  });
  const pipelineLayout = device.createPipelineLayout({ bindGroupLayouts: [bindGroupLayout] });

  const vertexModule = device.createShaderModule({ label: `${name}Vertex`, code: PASSTHRU_VERTEX_SOURCE });
  const fragmentModule = device.createShaderModule({ label: `${name}Fragment`, code: PASSTHRU_FRAGMENT_SOURCE });

  const pipeline = device.createRenderPipeline({
    layout: pipelineLayout,
    vertex: { module: vertexModule, entryPoint: 'main' },
    fragment: { module: fragmentModule, entryPoint: 'main', targets: [{ format }] },
    primitive: { topology: 'triangle-list', cullMode: 'none' },
  });

  const sampler = device.createSampler({
    magFilter: sampleMode,
    minFilter: sampleMode,
  });

  const placeholder = device.createTexture({
    size: { width: 1, height: 1 },
    format,
    usage: GPUTextureUsage.TEXTURE_BINDING,
  });
  let textureView = placeholder.createView();

  let bindGroup = device.createBindGroup({
    layout: bindGroupLayout,
    entries: [
      { binding: 0, resource: textureView },
      { binding: 1, resource: sampler },
    ],
  });

  const rebuildBindGroup = () => {
    bindGroup = device.createBindGroup({
      layout: bindGroupLayout,
      entries: [
        { binding: 0, resource: textureView },
        { binding: 1, resource: sampler },
      ],
    });
  };

  const handles: PassthruMaterialHandles = {
    pipeline,
    get bindGroup() { return bindGroup; },
    setTexture: (_name, texture) => {
      textureView = texture;
      rebuildBindGroup();
    },
    setUniforms: () => {},
  };

  return handles;
}

export class PassthruEffect extends CustomShaderEffect<PassthruUniforms, PassthruInputs> {
  override effectName = 'Passthru';

  constructor(
    device: GPUDevice,
    inputs: PassthruInputs,
    width = 1280,
    height = 720,
    format: GPUTextureFormat = 'rgba16float',
    clearColor: GPUColor = { r: 0, g: 0, b: 0, a: 1 },
    sampleMode: 'nearest' | 'linear' = 'linear',
  ) {
    super(device, inputs, {
      factory: (deviceRef, formatRef, options) =>
        createPassthruMaterial(deviceRef, formatRef, { name: options?.name, sampleMode }),
      textureInputKeys: ['src'],
      textureBindingKeys: ['src'],
      passCount: 1,
      primaryTextureKey: 'src',
      width,
      height,
      format,
      clearColor,
    });
  }
}

interface FeedbackInputs extends ShaderInputs {
  initialState: ShaderEffect;
}

export class FeedbackNode extends ShaderEffect<FeedbackInputs> {
  output: GPUTextureView;
  private readonly passthrough: PassthruEffect;
  private firstRender = true;
  private feedbackSrc?: ShaderEffect;
  override effectName = 'FeedbackNode';

  constructor(
    device: GPUDevice,
    startState: ShaderEffect,
    width = startState.width,
    height = startState.height,
    format: GPUTextureFormat = 'rgba16float',
    clearColor: GPUColor = { r: 0, g: 0, b: 0, a: 1 },
    sampleMode: 'nearest' | 'linear' = 'linear',
  ) {
    super();
    this.width = width;
    this.height = height;
    this.inputs = { initialState: startState };
    this.passthrough = new PassthruEffect(device, { src: startState.output }, width, height, format, clearColor, sampleMode);
    this.output = this.passthrough.output;
  }

  setFeedbackSrc(effect: ShaderEffect): void {
    this.feedbackSrc = effect;
  }

  setSrcs(inputs: Partial<FeedbackInputs>): void {
    if (!inputs.initialState) {
      return;
    }
    this.inputs = { initialState: inputs.initialState };
    this.passthrough.setSrcs({ src: inputs.initialState.output });
    this.firstRender = true;
  }

  setUniforms(_uniforms: ShaderUniforms): void {}

  updateUniforms(): void {}

  render(): void {
    this.passthrough.render();
    if (this.firstRender) {
      this.firstRender = false;
      if (this.feedbackSrc) {
        this.passthrough.setSrcs({ src: this.feedbackSrc.output });
      }
    }
  }

  dispose(): void {
    this.passthrough.dispose();
  }
}

