export const onCook: OnCook<typeof parameters> = (host) => {
  const p = host.params; // This callback's frozen snapshot; tuples are readonly.
  const input = host.inputs.get('value'); // Missing input = 0.

  host.outputs.set(
    'value',
    !p.Enabled ? input : p.Mode === 'multiply' ? input * p.Gain : input + p.Gain,
  );
  host.outputs.set('count', p.Count);
  host.outputs.set('x', p.Position[0]);
  host.outputs.set('y', p.Position[1]);
  host.outputs.set('z', p.Direction[2]);
  host.outputs.set('red', p.Color[0]);
  host.outputs.set('alpha', p.Tint[3]);
  host.outputs.set('textlength', p.Caption.length);
  host.outputs.set('pulses', pulses);
};

