import type { ParameterDefinitions } from '@avtools/native-webgpu/td-parameters';
import type { Draw, OnPulse } from '@avtools/native-webgpu/td-sketch';

export const parameters = {
  Size: { type: 'float', default: 70, min: 1, max: 300, clamp: true },
  Color: { type: 'rgb', default: [1, 0.45, 0.2] },
  Visible: { type: 'toggle', default: true },
  Shape: { type: 'menu', options: ['circle', 'square'] },
  Shuffle: { type: 'pulse' },
} as const satisfies ParameterDefinitions;

let x = 0.5;

export const onPulse: OnPulse<typeof parameters> = (name) => {
  if (name === 'Shuffle') {
    x = 0.15 + Math.random() * 0.7;
  }
};

export const draw: Draw<typeof parameters> = (p, frame) => {
  const controls = frame.params;

  p.background(24);

  if (!controls.Visible) {
    return;
  }

  p.noStroke();
  p.fill(controls.Color[0] * 255, controls.Color[1] * 255, controls.Color[2] * 255);

  const size = controls.Size;

  if (controls.Shape === 'circle') {
    p.circle(frame.width * x, frame.height / 2, size);
  } else {
    p.rect(frame.width * x - size / 2, frame.height / 2 - size / 2, size, size);
  }
};

sketches/timing/picture.ts:
import { launch } from '@avtools/core-timing';
import type { Setup, Draw } from '@avtools/native-webgpu/td-sketch';
import type { ParameterDefinitions } from '@avtools/native-webgpu/td-parameters';

export const parameters = {
  Speed: { type: 'float', default: 1, min: 0, max: 4 },
} as const satisfies ParameterDefinitions;

let phase = 0;

export const setup: Setup<typeof parameters> = (_p, host) => {
  let running = true;

  host.onDispose(() => {
    running = false;
  });

  launch(async (ctx) => {
    let previous = performance.now();

    while (running) {
      await ctx.waitSec(1 / 120); // Independent wall-clock timer, not a TD frame wait.

      if (!running) {
        return;
      }

      const now = performance.now();
      phase += ((now - previous) / 1000) * host.params.Speed;
      previous = now;
      // Read host.params here each time: don't retain an old snapshot over await.
      // With TD playback paused, time advances but TD only presents on a cook.
    }
  });
};

export const draw: Draw<typeof parameters> = (p, frame) => {
  p.background(24);
  p.noStroke();
  p.fill(80, 180, 255);
  p.circle(frame.width * (0.5 + 0.35 * Math.sin(phase)), frame.height / 2, 70);
};
